import pyomo.environ as pyo

DATA = {
    "centers": [1, 2, 3, 4, 5],
    "stores": [1, 2, 3, 4, 5, 6],
    "open_cost": {
        1: 151000, 2: 192000, 3: 114000, 4: 171000, 5: 160000,
    },
    "transport_cost": {
        (1, 1): 5, (1, 2): 2, (1, 3): 3, (1, 4): 3, (1, 5): 3, (1, 6): 5,
        (2, 1): 4, (2, 2): 3, (2, 3): 5, (2, 4): 2, (2, 5): 4, (2, 6): 2,
        (3, 1): 4, (3, 2): 5, (3, 3): 1, (3, 4): 4, (3, 5): 2, (3, 6): 5,
        (4, 1): 4, (4, 2): 1, (4, 3): 1, (4, 4): 3, (4, 5): 3, (4, 6): 2,
        (5, 1): 4, (5, 2): 4, (5, 3): 3, (5, 4): 4, (5, 5): 4, (5, 6): 1,
    },
    "demand": {
        1: 530, 2: 884, 3: 420, 4: 566, 5: 673, 6: 787,
    },
    "capacity": {
        1: 1400, 2: 1115, 3: 813, 4: 1041, 5: 1576,
    },
}

GOLD_ANSWER = None


def build_model(data=None):
    d = data or DATA
    model = pyo.ConcreteModel()

    model.I = pyo.Set(initialize=d["centers"])
    model.J = pyo.Set(initialize=d["stores"])
    model.IJ = pyo.Set(
        initialize=[(i, j) for i in d["centers"] for j in d["stores"]],
        dimen=2,
    )

    model.x = pyo.Var(
        model.IJ, within=pyo.NonNegativeReals, bounds=(0, None)
    )
    model.y = pyo.Var(model.I, within=pyo.Binary)

    def obj_rule(m):
        open_part = sum(d["open_cost"][i] * m.y[i] for i in m.I)
        ship_part = sum(
            d["transport_cost"][(i, j)] * m.x[i, j] for (i, j) in m.IJ
        )
        return open_part + ship_part

    model.obj = pyo.Objective(expr=obj_rule, sense=pyo.minimize)

    def demand_rule(m, j):
        return sum(m.x[i, j] for i in m.I) == d["demand"][j]

    model.demand = pyo.Constraint(model.J, rule=demand_rule)

    def capacity_rule(m, i):
        return (
            sum(m.x[i, j] for j in m.J)
            <= d["capacity"][i] * m.y[i]
        )

    model.capacity = pyo.Constraint(model.I, rule=capacity_rule)

    def link_rule(m, i, j):
        return m.x[i, j] <= d["capacity"][i] * m.y[i]

    model.link = pyo.Constraint(model.IJ, rule=link_rule)

    return model
